,"cb_reference"]},"data":{"type":["object","array"]},"retrieved_at":{"type":"string"}}}'::jsonb,ARRAY['crunchbase','official-data','company','people','funding','funding-rounds','investors','founders','leadership','board-members','employees','financials','profile','fetch','enrichment']::text[],ARRAY['Business','Finance'],'company','lookup','Official company, people and funding profiles','https://data.crunchbase.com/docs/tool-reference','official-provider-documentation-awaiting-oauth',now(),'https://mcp.crunchbase.com' FROM providers.apis WHERE slug='apimarket-magicapi-crunchbase-bbcca0a6'
